#include <iostream>
#include <vector>
#include <string>
struct Tracer {
    std::string s;
    Tracer(const char* p) : s(p) { std::cout << "ctor " << s << '\n'; }
    Tracer(const Tracer& o) : s(o.s) { std::cout << "copy " << s << '\n'; }
    Tracer(Tracer&& o) noexcept : s(std::move(o.s)) { std::cout << "move " << s << '\n'; }
};
int main() {
    std::vector<Tracer> v;
    v.reserve(2);
    v.push_back(Tracer("a"));   // 先构造临时对象，再移动进容器
    v.emplace_back("b");        // 在容器内就地构造，省一次移动
    std::cout << "done\n";
}
